/**
 * History: what each tier has actually done on each task size, plus the
 * prior that stands in until there is enough of it.
 */
import { ceilingNanos } from '../schema/money.js';
import type { TallyConfig, TaskSize } from '../schema/types.js';
import type { AttemptOutcome, PriceHistoryPort, PriceHistoryWriterPort, PriceStats } from './ports.js';

export interface Prior {
  passRate: number;
  avgCostNanos: number;
}

/** A prior blended with what was observed. `attempts` counts observations only. */
export interface Estimate extends Prior {
  attempts: number;
}

/** How many observed attempts the prior is worth. */
export const DEFAULT_PRIOR_WEIGHT = 2;

/** Assumed pass rate of the cheapest and the strongest tier, before any history. */
const PRIOR_PASS_RATE: Record<TaskSize, readonly [cheapest: number, top: number]> = {
  small: [0.7, 0.95],
  medium: [0.45, 0.9],
  large: [0.2, 0.85],
};

/** Position of a tier in the config, from 0 (cheapest) to 1 (strongest). */
export function tierRank(config: TallyConfig, tierName: string): number {
  const index = config.tiers.findIndex((tier) => tier.name === tierName);
  if (index < 0) throw new Error(`Tier "${tierName}" is not in tally.yaml`);
  return config.tiers.length === 1 ? 1 : index / (config.tiers.length - 1);
}

/**
 * The assumption used when a (size, tier) pair has no history: the pass rate
 * rises with the tier's position, and an attempt costs its full ceiling.
 */
export function priorFor(config: TallyConfig, size: TaskSize, tierName: string): Prior {
  const rank = tierRank(config, tierName);
  const [cheapest, top] = PRIOR_PASS_RATE[size];
  const tier = config.tiers.find((candidate) => candidate.name === tierName)!;
  return {
    passRate: cheapest + (top - cheapest) * rank,
    avgCostNanos: ceilingNanos(config, size, tier),
  };
}

export function blend(observed: PriceStats | null, prior: Prior, priorWeight = DEFAULT_PRIOR_WEIGHT): Estimate {
  if (!observed || observed.attempts <= 0) return { ...prior, attempts: 0 };
  const total = observed.attempts + priorWeight;
  return {
    passRate: (observed.passRate * observed.attempts + prior.passRate * priorWeight) / total,
    avgCostNanos: Math.round((observed.avgCostNanos * observed.attempts + prior.avgCostNanos * priorWeight) / total),
    attempts: observed.attempts,
  };
}

/** Pass rate and average cost to plan with. Never fails: unreadable history means the prior. */
export async function estimateFor(
  config: TallyConfig,
  history: PriceHistoryPort | undefined,
  size: TaskSize,
  tierName: string,
  priorWeight = DEFAULT_PRIOR_WEIGHT,
): Promise<Estimate> {
  const prior = priorFor(config, size, tierName);
  let observed: PriceStats | null = null;
  try {
    observed = (await history?.lookup(size, tierName)) ?? null;
  } catch {
    observed = null;
  }
  return blend(observed, prior, priorWeight);
}

interface Cell {
  attempts: number;
  passes: number;
  totalCostNanos: number;
}

export interface PriceHistorySnapshot {
  version: 1;
  /** Keyed by `${size}:${tier}`. */
  cells: Record<string, Cell>;
}

function isCell(value: unknown): value is Cell {
  if (typeof value !== 'object' || value === null) return false;
  const cell = value as Record<string, unknown>;
  return [cell.attempts, cell.passes, cell.totalCostNanos].every((n) => typeof n === 'number' && Number.isFinite(n) && n >= 0);
}

/**
 * Local history, kept in memory. The engine saves `snapshot()` wherever it
 * keeps run output and passes it back in on the next run.
 */
export class PriceHistory implements PriceHistoryPort, PriceHistoryWriterPort {
  private readonly cells = new Map<string, Cell>();

  constructor(snapshot?: PriceHistorySnapshot) {
    if (snapshot?.version !== 1 || typeof snapshot.cells !== 'object' || snapshot.cells === null) return;
    for (const [key, cell] of Object.entries(snapshot.cells)) {
      if (isCell(cell)) this.cells.set(key, { ...cell });
    }
  }

  async lookup(size: TaskSize, tier: string): Promise<PriceStats | null> {
    const cell = this.cells.get(`${size}:${tier}`);
    if (!cell || cell.attempts === 0) return null;
    return {
      attempts: cell.attempts,
      passRate: cell.passes / cell.attempts,
      avgCostNanos: Math.round(cell.totalCostNanos / cell.attempts),
    };
  }

  async record(outcome: AttemptOutcome): Promise<void> {
    // An errored attempt broke outside the model, so it says nothing about the tier.
    if (outcome.result === 'error') return;
    const key = `${outcome.size}:${outcome.tier}`;
    const cell = this.cells.get(key) ?? { attempts: 0, passes: 0, totalCostNanos: 0 };
    cell.attempts += 1;
    if (outcome.result === 'passed') cell.passes += 1;
    cell.totalCostNanos += outcome.costNanos;
    this.cells.set(key, cell);
  }

  snapshot(): PriceHistorySnapshot {
    return { version: 1, cells: Object.fromEntries([...this.cells].map(([key, cell]) => [key, { ...cell }])) };
  }
}
import { describe, expect, it } from 'vitest';
import { usdToNanos } from '../schema/money.js';
import { PriceHistory, blend, estimateFor, priorFor } from './history.js';
import { FakeHistory, sampleConfig } from './testing/fakes.js';

const config = sampleConfig();

describe('priorFor', () => {
  it('expects stronger tiers to pass more often', () => {
    for (const size of ['small', 'medium', 'large'] as const) {
      const [bronze, silver, gold] = ['bronze', 'silver', 'gold'].map((tier) => priorFor(config, size, tier).passRate);
      expect(bronze!).toBeLessThan(silver!);
      expect(silver!).toBeLessThan(gold!);
    }
  });

  it('expects larger tasks to pass less often on the same tier', () => {
    expect(priorFor(config, 'large', 'bronze').passRate).toBeLessThan(priorFor(config, 'small', 'bronze').passRate);
  });

  it('assumes an attempt costs its ceiling until shown otherwise', () => {
    expect(priorFor(config, 'medium', 'gold').avgCostNanos).toBe(usdToNanos(4));
    expect(priorFor(config, 'medium', 'bronze').avgCostNanos).toBe(usdToNanos(0.8));
  });

  it('treats a single configured tier as the top tier', () => {
    const one = sampleConfig({ tiers: [config.tiers[0]!] });
    expect(priorFor(one, 'small', 'bronze').passRate).toBe(priorFor(config, 'small', 'gold').passRate);
  });

  it('rejects a tier that is not in the config', () => {
    expect(() => priorFor(config, 'small', 'platinum')).toThrow(/platinum/);
  });
});

describe('blend', () => {
  const prior = { passRate: 0.7, avgCostNanos: 300 };

  it('returns the prior when nothing has been observed', () => {
    expect(blend(null, prior)).toEqual({ ...prior, attempts: 0 });
    expect(blend({ attempts: 0, passRate: 0, avgCostNanos: 0 }, prior)).toEqual({ ...prior, attempts: 0 });
  });

  it('counts the prior as two attempts', () => {
    const estimate = blend({ attempts: 2, passRate: 0, avgCostNanos: 100 }, prior);
    expect(estimate.passRate).toBeCloseTo(0.35);
    expect(estimate.avgCostNanos).toBe(200);
    expect(estimate.attempts).toBe(2);
  });

  it('is dominated by the observations once there are many', () => {
    expect(blend({ attempts: 1000, passRate: 0.1, avgCostNanos: 100 }, prior).passRate).toBeCloseTo(0.1, 2);
  });
});

describe('estimateFor', () => {
  it('falls back to the prior when the history cannot be read', async () => {
    const history = new FakeHistory();
    history.failWith = new Error('neatlogs unreachable');
    const estimate = await estimateFor(config, history, 'small', 'bronze');
    expect(estimate).toEqual({ ...priorFor(config, 'small', 'bronze'), attempts: 0 });
  });

  it('works with no history port at all', async () => {
    expect((await estimateFor(config, undefined, 'small', 'gold')).attempts).toBe(0);
  });
});

describe('PriceHistory', () => {
  it('has nothing to report before the first attempt', async () => {
    expect(await new PriceHistory().lookup('small', 'bronze')).toBeNull();
  });

  it('updates pass rate and average cost after every attempt', async () => {
    const history = new PriceHistory();
    await history.record({ size: 'small', tier: 'bronze', result: 'passed', costNanos: 100 });
    expect(await history.lookup('small', 'bronze')).toEqual({ attempts: 1, passRate: 1, avgCostNanos: 100 });
    await history.record({ size: 'small', tier: 'bronze', result: 'failed', costNanos: 300 });
    expect(await history.lookup('small', 'bronze')).toEqual({ attempts: 2, passRate: 0.5, avgCostNanos: 200 });
    await history.record({ size: 'small', tier: 'bronze', result: 'stopped', costNanos: 500 });
    expect(await history.lookup('small', 'bronze')).toEqual({ attempts: 3, passRate: 1 / 3, avgCostNanos: 300 });
  });

  it('keeps each size and tier apart', async () => {
    const history = new PriceHistory();
    await history.record({ size: 'small', tier: 'bronze', result: 'passed', costNanos: 100 });
    expect(await history.lookup('medium', 'bronze')).toBeNull();
    expect(await history.lookup('small', 'silver')).toBeNull();
  });

  it('ignores attempts that errored, since they say nothing about the model', async () => {
    const history = new PriceHistory();
    await history.record({ size: 'small', tier: 'bronze', result: 'error', costNanos: 100 });
    expect(await history.lookup('small', 'bronze')).toBeNull();
  });

  it('survives a round trip through JSON', async () => {
    const history = new PriceHistory();
    await history.record({ size: 'large', tier: 'gold', result: 'passed', costNanos: 700 });
    const restored = new PriceHistory(JSON.parse(JSON.stringify(history.snapshot())));
    expect(await restored.lookup('large', 'gold')).toEqual({ attempts: 1, passRate: 1, avgCostNanos: 700 });
  });

  it('starts empty from a snapshot it cannot read', async () => {
    const restored = new PriceHistory({ version: 99, cells: 'nope' } as never);
    expect(await restored.lookup('large', 'gold')).toBeNull();
  });

  it('feeds the estimate', async () => {
    const history = new PriceHistory();
    for (let i = 0; i < 8; i += 1) {
      await history.record({ size: 'small', tier: 'bronze', result: 'failed', costNanos: usdToNanos(0.3) });
    }
    const estimate = await estimateFor(config, history, 'small', 'bronze');
    expect(estimate.passRate).toBeCloseTo((0.7 * 2) / 10);
    expect(estimate.attempts).toBe(8);
  });
});

