async function runAttempt(input: {
  runId: string;
  task: BacklogTask;
  attempt: number;
  tier: Tier;
  ceilingNanos: number | null;
  decision: string;
  escalatedFrom: string | null;
  handoff: LedgerRow['handoff'];
  handoffSummary: string | null;
  config: TallyConfig;
  configPath: string;
  ports: RealRunPorts;
