    entire: config.integrations.entire ? { status: 'ok', detail: null } : { status: 'off', detail: null },
    cfoai: config.integrations.cfoai ? { status: 'missing', detail: 'CSV fallback not implemented yet.' } : { status: 'off', detail: null },
