    expect(result.runState.tasks).toHaveLength(3);
    expect(result.ledger.map((row) => `${row.taskId}:${row.attempt}:${row.result}:${row.tier}`)).toEqual([
      'T1:1:passed:cheap',
      'T2:1:stopped:middle',
      'T2:2:passed:top',
      'T3:1:passed:top',
