            attempt: 1,
            size: 'small',
            tier: 'cheap',
            model: 'claude-haiku-4-5-20251001',
            harness: 'claude-code',
            sessionId: 'session-old',
            branch: 'tally/t1-old',
            tokens,
            estimatedCostNanos: 500_000_000,
            costSource: 'list-price',
            ceilingNanos: 200_000_000,
            result: 'failed',
            resultReason: 'tests failed before interruption',
            escalatedFrom: null,
            handoff: 'none',
            prUrl: null,
            traceUrl: null,
            checkpointId: null,
