}

function defaultOutputDir(runId: string): string {
  const base = resolve(`.tally/runs/${runId}`);
  if (!existsSync(base)) return base;
  for (let i = 2; ; i += 1) {
    const candidate = resolve(`.tally/runs/${runId}-${i}`);
    if (!existsSync(candidate)) return candidate;
