    const why = passedOver(cheaper);
    const ending = `${top.name} with a ${usd(topCeiling)} ceiling`;
    return {
      ...common,
      action: 'start',
      tier: top,
      ceilingNanos: topCeiling,
      expectedCostNanos: topCost,
      topCostNanos: topCost,
      reason: why
