const fs = require('fs');
function summarize(path) {
  const data = JSON.parse(fs.readFileSync(path, 'utf8'));
  const names = [];
  const texts = [];
  function walk(value, key='') {
    if (Array.isArray(value)) value.forEach((v, i) => walk(v, `${key}[${i}]`));
    else if (value && typeof value === 'object') {
      if (typeof value.name === 'string') names.push(value.name);
      for (const [k, v] of Object.entries(value)) walk(v, k);
    } else if (typeof value === 'string') texts.push(value);
  }
  walk(data);
  const hookish = [...new Set([...names, ...texts.filter((s) => /neatlogs|entire/i.test(s)).map((s) => s.replace(/.*?(neatlogs[^\s\"]+|entire[^\s\"]*).*/i, '$1'))])].sort();
  return { path, hookish };
}
