{"cmd":"node - <<'NODE'
const fs=require('fs'), os=require('os'), path=require('path'), crypto=require('crypto');
const root=path.join(os.homedir(), '.claude', 'projects');
const dirs=fs.readdirSync(root).filter(d=>d.includes('neatlogs-claude-global-check'));
const files=dirs.flatMap(d=>fs.readdirSync(path.join(root,d)).filter(f=>f.endsWith('.jsonl')).map(f=>path.join(root,d,f)));
files.sort((a,b)=>fs.statSync(b).mtimeMs-fs.statSync(a).mtimeMs);
const file=files[0];
const lines=fs.readFileSync(file,'utf8').trim().split('\n').map(l=>JSON.parse(l));
const sessionId=lines.find(x=>x.sessionId)?.sessionId;
function deterministicId(input, bytes) { return crypto.createHash('sha256').update(input).digest().subarray(0, bytes).toString('hex'); }
console.log(JSON.stringify({ transcript: file, sessionId, traceId: deterministicId(`${sessionId}:turn:1`, 16) }, null, 2));
