      fallback: new FakeHistory(null),
      env: { NEATLOGS_TOKEN: 'token', NEATLOGS_PROJECT_ID: 'project' },
      endpoint: 'https://app.neatlogs.test/api/v1/public',
      fetch: async (input, init) => {
        calls.push(`${input}`);
