        expect((init?.headers as Record<string, string>)['x-project-id']).toBe('project');
        if (`${input}`.includes('/traces?')) return response({ traces: [{ id: 'trace-1' }, { traceId: 'trace-2' }] });
        if (`${input}`.endsWith('/trace-1/spans')) {
          return response({
            spans: [
