import { describe, expect, it } from 'vitest';
import { usdToNanos } from '../schema/money.js';
import type { TaskSize } from '../schema/types.js';
import { routeTask, type RouteDecision } from './router.js';
import type { SizeEstimate } from './sizer.js';
import { FakeBudget, FakeHistory, RecordingTrace, sampleConfig, task } from './testing/fakes.js';

const config = sampleConfig();

function estimate(size: TaskSize, confidence: number): SizeEstimate {
  return {
    size,
    confidence,
    signals: { filesTouched: 1, dependents: 0, testsPresent: true, source: 'entire-graph' },
    specificity: 0.5,
    refinedBy: 'rules',
    summary: '1 file touched, no dependents and tests present',
  };
}

async function route(
  size: TaskSize,
  confidence: number,
  budgetUsd = 40,
  history = new FakeHistory(),
  cfg = config,
): Promise<RouteDecision> {
  return routeTask({
    task: task(),
    estimate: estimate(size, confidence),
    config: cfg,
    ports: { history, budget: new FakeBudget(usdToNanos(budgetUsd)) },
  });
}

function started(decision: RouteDecision) {
  if (decision.action !== 'start') throw new Error(`expected a start, got: ${decision.reason}`);
  return decision;
}

/** Enough observations that the prior no longer matters. */
const seen = (passRate: number, avgUsd: number) => ({ attempts: 1000, passRate, avgCostNanos: usdToNanos(avgUsd) });

function expectOneSentence(reason: string): void {
  expect(reason).toMatch(/^[A-Z].*\.$/);
  expect(reason).not.toMatch(/[.!?]\s/);
  expect(reason).not.toContain('\n');
}

describe('routeTask', () => {
  it('chooses the cheapest tier when the sizer is confident', async () => {
    const decision = started(await route('small', 0.9));
    expect(decision.tier.name).toBe('bronze');
    expect(decision.ceilingNanos).toBe(usdToNanos(0.3));
    expect(decision.reason).toContain('bronze');
    expect(decision.reason).toContain('$0.30');
  });

  it('chooses the cheapest tier for a small, tested, well-specified task with no history', async () => {
    const decision = started(
      await routeTask({
        task: task({
          title: 'Reject negative refunds',
          body: 'Calling `refund.validate(-5)` in src/refund/validator.ts should raise an error, but it returns true.',
        }),
        estimate: {
          size: 'small',
          confidence: 0.65,
          signals: { filesTouched: 1, dependents: 0, testsPresent: true, source: 'code-search' },
          specificity: 0.65,
          refinedBy: 'rules',
          summary: '1 file touched, no dependents and tests present',
        },
        config,
        ports: { budget: new FakeBudget(usdToNanos(40)) },
      }),
    );
    expect(decision.tier.name).toBe('bronze');
    expect(decision.ceilingNanos).toBe(usdToNanos(0.3));
    expect(decision.expectedCostNanos).toBe(usdToNanos(0.75));
    expect(decision.topCostNanos).toBe(usdToNanos(1.5));
  });

  it('caps the cheap attempt at 20% of what the top tier may spend', async () => {
    const decision = started(await route('medium', 0.9));
    expect(decision.tier.name).toBe('bronze');
    expect(decision.ceilingNanos).toBe(usdToNanos(4) * 0.2);
  });

  it('goes straight to the strongest tier when the sizer is unsure', async () => {
    const decision = started(await route('small', 0.2));
    expect(decision.tier.name).toBe('gold');
    expect(decision.ceilingNanos).toBe(usdToNanos(1.5));
    expect(decision.reason).toMatch(/uncertain/);
  });

  it('starts in the middle when it is sure enough for that but not for the cheapest', async () => {
    const decision = started(await route('medium', 0.5));
    expect(decision.tier.name).toBe('silver');
    expect(decision.reason).toMatch(/uncertain for bronze/);
  });

  it('applies the rule: ceiling + P(fail) x top cost must be below top cost', async () => {
    // Small: top cost 1.50, bronze ceiling 0.30. Break-even is a failure rate of 80%.
    const fails85 = new FakeHistory().set('small', 'bronze', seen(0.15, 0.3));
    expect(started(await route('small', 0.95, 40, fails85)).tier.name).not.toBe('bronze');

    const fails50 = new FakeHistory().set('small', 'bronze', seen(0.5, 0.3));
    const decision = started(await route('small', 0.95, 40, fails50));
    expect(decision.tier.name).toBe('bronze');
    // 0.30 + 0.5 x 1.50, give or take the prior's small pull.
    expect(decision.expectedCostNanos / 1e9).toBeCloseTo(1.05, 2);
    expect(decision.topCostNanos).toBe(usdToNanos(1.5));
  });

  it('stops sending a size to a tier that keeps failing it, however confident the sizer is', async () => {
    const history = new FakeHistory()
      .set('small', 'bronze', seen(0.05, 0.3))
      .set('small', 'silver', seen(0.05, 0.75));
    const decision = started(await route('small', 1, 40, history));
    expect(decision.tier.name).toBe('gold');
    expect(decision.reason).toMatch(/fail/);
  });

  it('never sends a large task to the cheapest tier on the prior alone', async () => {
    expect(started(await route('large', 1)).tier.name).not.toBe('bronze');
  });

  it('goes straight to the top when the top tier already costs less than a cheap ceiling', async () => {
    const history = new FakeHistory().set('small', 'gold', seen(0.95, 0.2));
    const decision = started(await route('small', 1, 40, history));
    expect(decision.tier.name).toBe('gold');
  });

  it('uses the prior when the history cannot be read', async () => {
    const history = new FakeHistory();
    history.failWith = new Error('unreachable');
    expect(started(await route('small', 0.9, 40, history)).tier.name).toBe('bronze');
  });

  describe('budget', () => {
    it('starts nothing when no ceiling fits the budget left', async () => {
      const decision = await route('small', 0.9, 0.1);
      expect(decision.action).toBe('skip');
      if (decision.action !== 'skip') return;
      expect(decision.statusReason).toBe('not started: no budget');
      expect(decision.reason).toContain('$0.10');
      expectOneSentence(decision.reason);
    });

    it('starts a task whose ceiling exactly fits', async () => {
      expect(started(await route('small', 0.9, 0.3)).tier.name).toBe('bronze');
    });

    it('falls back to a cheaper tier that fits when the preferred one does not', async () => {
      const decision = started(await route('small', 0.2, 0.5));
      expect(decision.tier.name).toBe('bronze');
      expect(decision.reason).toMatch(/budget/);
    });

    it('does not burn the last of the budget on an attempt that will probably fail', async () => {
      // Large: gold needs 10, silver 5, bronze 2. Only bronze fits, and it passes ~20% of the time.
      expect((await route('large', 0.2, 2.5)).action).toBe('skip');
    });

    it('never starts an attempt whose ceiling is above the budget left', async () => {
      for (const size of ['small', 'medium', 'large'] as const) {
        for (const confidence of [0, 0.3, 0.5, 0.8, 1]) {
          for (const budgetUsd of [0, 0.05, 0.3, 0.5, 0.8, 1, 2, 3.9, 5, 9.99, 10, 40]) {
            const decision = await route(size, confidence, budgetUsd);
            if (decision.action === 'start') expect(decision.ceilingNanos).toBeLessThanOrEqual(usdToNanos(budgetUsd));
          }
        }
      }
    });
  });

  describe('tiers come from the config', () => {
    it('works with a single tier', async () => {
      const one = sampleConfig({ tiers: [{ ...config.tiers[2]!, name: 'only' }] });
      const decision = started(await route('small', 0.9, 40, new FakeHistory(), one));
      expect(decision.tier.name).toBe('only');
      expectOneSentence(decision.reason);
    });

    it('works with two tiers and any names', async () => {
      const two = sampleConfig({
        tiers: [
          { ...config.tiers[0]!, name: 'intern' },
          { ...config.tiers[2]!, name: 'principal' },
        ],
      });
      expect(started(await route('small', 0.9, 40, new FakeHistory(), two)).tier.name).toBe('intern');
      expect(started(await route('small', 0.1, 40, new FakeHistory(), two)).tier.name).toBe('principal');
    });

    it('returns the whole tier, so the caller needs no model table of its own', async () => {
      const decision = started(await route('small', 0.9));
      expect(decision.tier).toBe(config.tiers[0]);
    });
  });

  it('gives a one-sentence reason for every decision', async () => {
    for (const size of ['small', 'medium', 'large'] as const) {
      for (const confidence of [0, 0.4, 0.6, 1]) {
        for (const budgetUsd of [0.1, 0.5, 2.5, 40]) {
          expectOneSentence((await route(size, confidence, budgetUsd)).reason);
        }
      }
    }
  });

  it('traces the routing decision when a trace port is provided', async () => {
    const trace = new RecordingTrace();
    const decision = await routeTask({
      task: task(),
      estimate: estimate('small', 0.9),
      config,
      ports: { budget: new FakeBudget(usdToNanos(40)), trace },
    });
    expect(decision.action).toBe('start');
    expect(trace.spans).toHaveLength(1);
    expect(trace.spans[0]).toMatchObject({
      name: 'tally.route',
      attributes: { taskId: 'T1', size: 'small', confidence: 0.9, action: 'start', tier: 'bronze' },
      error: null,
    });
  });
});

item.stdout:
/**
 * The routing rule: which tier a task starts on.
 *
 * A task goes to a cheaper tier only when
 *
 *     cheap ceiling + P(cheap fails) x top cost  <  top cost
 *
 * and the sizer is confident enough in what the task is. Otherwise it goes
 * to a stronger tier. Nothing starts unless its ceiling fits the budget left.
 */
import { ceilingNanos, nanosToUsd } from '../schema/money.js';
import type { TallyConfig, TaskSize, Tier } from '../schema/types.js';
import { DEFAULT_PRIOR_WEIGHT, estimateFor, tierRank } from './history.js';
import type { BudgetPort, PriceHistoryPort, TaskInput, TraceAttributes, TracePort } from './ports.js';
import type { SizeEstimate } from './sizer.js';
import { traceDecision } from './trace.js';

export interface RoutingOptions {
  /**
   * Confidence the cheapest tier needs. Tiers in between need proportionally
   * less, and the strongest tier needs none.
   */
  cheapConfidence: number;
  /** How many observed attempts the prior is worth. */
  priorWeight: number;
  /**
   * When the budget rules out the preferred tier, a cheaper one is tried
   * only if it is expected to pass at least this often.
   */
  minPassRateOnTightBudget: number;
}

export const DEFAULT_ROUTING: RoutingOptions = {
  cheapConfidence: 0.65,
  priorWeight: DEFAULT_PRIOR_WEIGHT,
  minPassRateOnTightBudget: 0.5,
};

export interface StartDecision {
  action: 'start';
  taskId: string;
  size: TaskSize;
  confidence: number;
  /** The tier to run, straight from tally.yaml. */
  tier: Tier;
  /** Spend ceiling for the attempt. Null means no ceiling (baseline mode only). */
  ceilingNanos: number | null;
  /** Ceiling plus the chance of failing times the top cost; for the top tier, its estimated cost. */
  expectedCostNanos: number;
  /** Estimated cost of sending this task straight to the strongest tier. */
  topCostNanos: number;
  /** One plain-English sentence, shown on the dashboard and stored on the ledger row. */
  reason: string;
}

export interface SkipDecision {
  action: 'skip';
  taskId: string;
  size: TaskSize;
  confidence: number;
  /** Goes into TaskState.statusReason. */
  statusReason: 'not started: no budget';
  reason: string;
}

export type RouteDecision = StartDecision | SkipDecision;

export interface RouteInput {
  task: TaskInput;
  estimate: SizeEstimate;
  config: TallyConfig;
  ports: { history?: PriceHistoryPort; budget: BudgetPort; trace?: TracePort };
  options?: Partial<RoutingOptions>;
  traceAttributes?: TraceAttributes;
}

export function usd(nanos: number): string {
  return `$${nanosToUsd(nanos).toFixed(2)}`;
}

function percent(share: number): string {
  return `${Math.round(share * 100)}%`;
}

function capitalise(text: string): string {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

interface Candidate {
  tier: Tier;
  ceiling: number;
  passRate: number;
  expected: number;
  neededConfidence: number;
  worthIt: boolean;
  confident: boolean;
  fits: boolean;
}

async function routeTaskCore(input: RouteInput): Promise<RouteDecision> {
  const { task, estimate, config } = input;
  const options = { ...DEFAULT_ROUTING, ...input.options };
  const { size, confidence } = estimate;
  const top = config.tiers[config.tiers.length - 1];
  if (!top) throw new Error('tally.yaml has no tiers');

  const remaining = Math.max(0, await input.ports.budget.remainingNanos());
  const topCost = (await estimateFor(config, input.ports.history, size, top.name, options.priorWeight)).avgCostNanos;
  const topCeiling = ceilingNanos(config, size, top);
  const subject = `${size} task with ${estimate.summary}`;
  const common = { taskId: task.taskId, size, confidence };

  const cheaper: Candidate[] = [];
  for (const tier of config.tiers.slice(0, -1)) {
    const { passRate } = await estimateFor(config, input.ports.history, size, tier.name, options.priorWeight);
    const ceiling = ceilingNanos(config, size, tier);
    const expected = Math.round(ceiling + (1 - passRate) * topCost);
    const neededConfidence = options.cheapConfidence * (1 - tierRank(config, tier.name));
    cheaper.push({
      tier,
      ceiling,
      passRate,
      expected,
      neededConfidence,
      worthIt: expected < topCost,
      confident: confidence >= neededConfidence,
      fits: ceiling <= remaining,
    });
  }

  // Why the tiers below the chosen one were passed over, most telling first.
  const passedOver = (below: Candidate[]): string | null => {
    const unsure = below.find((c) => c.worthIt && !c.confident);
    if (unsure) {
      return `${capitalise(subject)} is too uncertain for ${unsure.tier.name} (confidence ${confidence.toFixed(2)} of ${unsure.neededConfidence.toFixed(2)} needed)`;
    }
    const failing = below.find((c) => !c.worthIt);
    if (failing) {
      return `${capitalise(failing.tier.name)} is expected to fail ${percent(1 - failing.passRate)} of ${size} tasks, too often for an attempt capped at ${usd(failing.ceiling)} to beat ${usd(topCost)} on ${top.name}`;
    }
    return null;
  };

  const chosenIndex = cheaper.findIndex((c) => c.worthIt && c.confident && c.fits);
  const chosen = cheaper[chosenIndex];
  if (chosen) {
    const why = passedOver(cheaper.slice(0, chosenIndex));
    const odds = `expected to cost ${usd(chosen.expected)} against ${usd(topCost)} for going straight to ${top.name}`;
    const reason = why
      ? `${why}, so it starts on ${chosen.tier.name} capped at ${usd(chosen.ceiling)}, ${odds}.`
      : `${capitalise(subject)}, so a ${chosen.tier.name} attempt capped at ${usd(chosen.ceiling)} is ${odds}.`;
    return {
      ...common,
      action: 'start',
      tier: chosen.tier,
      ceilingNanos: chosen.ceiling,
      expectedCostNanos: chosen.expected,
      topCostNanos: topCost,
      reason,
    };
  }

  if (topCeiling <= remaining) {
    const why = passedOver(cheaper);
    const ending = `${top.name} with a ${usd(topCeiling)} ceiling`;
    return {
      ...common,
      action: 'start',
      tier: top,
      ceilingNanos: topCeiling,
      expectedCostNanos: topCost,
      topCostNanos: topCost,
      reason: why
        ? `${why}, so it goes straight to ${ending}.`
        : `${capitalise(subject)} goes to ${ending}, the only tier configured.`,
    };
  }

  // The preferred tier does not fit. Take the strongest one that does, if it has a fair chance.
  const fallback = [...cheaper]
    .reverse()
    .find((c) => c.fits && c.passRate >= options.minPassRateOnTightBudget);
  if (fallback) {
    return {
      ...common,
      action: 'start',
      tier: fallback.tier,
      ceilingNanos: fallback.ceiling,
      expectedCostNanos: fallback.expected,
      topCostNanos: topCost,
      reason: `Only ${usd(remaining)} of budget is left, which does not cover the ${usd(topCeiling)} ceiling on ${top.name}, so this ${size} task gets a ${fallback.tier.name} attempt capped at ${usd(fallback.ceiling)}.`,
    };
  }

  const smallest = Math.min(topCeiling, ...cheaper.map((c) => c.ceiling));
  return {
    ...common,
    action: 'skip',
    statusReason: 'not started: no budget',
    reason:
      smallest > remaining
        ? `Not started because only ${usd(remaining)} of budget is left and the smallest ceiling for this ${size} task is ${usd(smallest)}.`
        : `Not started because only ${usd(remaining)} of budget is left, and no tier that fits it is likely to finish this ${size} task.`,
  };
}

export async function routeTask(input: RouteInput): Promise<RouteDecision> {
  return traceDecision(
    input.ports.trace,
    'tally.route',
    { ...input.traceAttributes, taskId: input.task.taskId, size: input.estimate.size, confidence: input.estimate.confidence },
    async (span) => {
      const decision = await routeTaskCore(input);
      span.set({
        action: decision.action,
        tier: decision.action === 'start' ? decision.tier.name : null,
        ceilingNanos: decision.action === 'start' ? decision.ceilingNanos : null,
        reason: decision.reason,
      });
      return decision;
    },
  );
}

