    await this.runner.run('entire', ['graph', 'index', '--repo', this.repoPath]);
    const search = await this.runner.run('entire', [
      'graph',
      'search',
      '--repo',
      this.repoPath,
      '--profile',
      'full',
      '--format',
      'json',
      '--query',
      query,
    ]);
