  ) {}

  async remainingNanos(): Promise<number> {
    const spent = this.ledger.reduce((sum, row) => sum + row.estimatedCostNanos, 0);
    return this.limitNanos - this.committedBeforeRunNanos - spent - this.reservedNanos;
