      } catch {
        // Some terms will not match; keep trying the rest.
      }
    }
    if (files.size === 0) return null;
    return {
      filesTouched: files.size,
      dependents: 0,
      testsPresent: [...files].some(looksLikeTest),
      source: 'code-search',
    };

