class FakeWorker implements WorkerPort, LiveUsagePort, SessionControlPort {
  starts: WorkerStartInput[] = [];
  stopped: string[] = [];
  published: Array<{ branch: string; taskId: string }> = [];
  commitsAheadCount = 1;

  async start(input: WorkerStartInput) {
    this.starts.push(input);
