import { readFileSync } from 'node:fs';
const envText = readFileSync(`${process.env.HOME}/.tally/.env`, 'utf8');
const env = Object.fromEntries(envText.split(/\r?\n/).flatMap((line) => {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) return [];
  const idx = trimmed.indexOf('=');
  if (idx < 0) return [];
  return [[trimmed.slice(0, idx), trimmed.slice(idx + 1).replace(/^['"]|['"]$/g, '')]];
}));
const token = env.NEATLOGS_TOKEN;
const project = env.NEATLOGS_PROJECT_ID;
