const EXPECTED_BEHAVIOUR = /\b(should|expected|must|instead of|returns?|raises?|throws?|fails?|error)\b/i;
const STEPS_OR_OUTPUT = /^\s*(\d+[.)]|[-*])\s+\S|```|Traceback|\bat .+:\d+/m;

