function buildPrompt(task: TaskInput, rules: SizeEstimate): string {
  const signals = rules.signals;
  return [
    'Estimate how big this coding task is for an autonomous coding agent.',
    '',
    `Title: ${task.title}`,
    `Issue: ${task.body.slice(0, 4000) || '(empty)'}`,
    '',
