export interface WorkerStartInput {
  task: BacklogTask;
  attempt: number;
  tier: Tier;
  ceilingNanos: number | null;
  harness: string;
  sessionMode?: 'chat' | 'tui';
  model: string;
  name: string;
  prompt: string;
  aoProject?: string;
}

export interface WorkerResult {
  status: 'idle' | 'terminated' | 'needs_input' | 'timeout';
  branch: string | null;
  checkoutPath: string | null;
  prUrl: string | null;
  resultReason?: string | null;
}

export interface WorkerPort {
  start(input: WorkerStartInput): Promise<{ sessionId: string; branch: string | null; checkoutPath: string | null }>;
  wait(sessionId: string, options?: { timeoutMs?: number }): Promise<WorkerResult>;
}

  ceilingNanos: number | null;
  decision: string;
  escalatedFrom: string | null;
  handoff: LedgerRow['handoff'];
  handoffSummary: string | null;
  traceId: string | null;
  config: TallyConfig;
  configPath: string;
  ports: RealRunPorts;
  now: () => Date;
  dryRun: boolean;
}): Promise<LedgerRow> {
  const startedAt = input.now().toISOString();
  const started = await input.ports.worker.start({
    task: input.task,
    attempt: input.attempt,
    tier: input.tier,
    ceilingNanos: input.ceilingNanos,
    harness: input.tier.harness,
    sessionMode: input.tier.sessionMode,
    model: input.tier.model,
    name: `tally-${input.runId}-${input.task.taskId}-${input.attempt}`,
    prompt: promptFor(input.task, input.config, input.tier, input.handoffSummary, input.runId, input.attempt),
    aoProject: input.config.repo.aoProject,
  });
  const watcher = new CeilingWatcher({ usage: input.ports.usage, sessions: input.ports.sessions, trace: input.ports.trace });
  const abort = new AbortController();
  const watched = watcher.watch(
    { sessionId: started.sessionId, tier: input.tier, ceilingNanos: input.ceilingNanos },
    { signal: abort.signal, intervalMs: input.dryRun ? 1 : 5000 },
  );
  const worker = input.ports.worker.wait(started.sessionId, { timeoutMs: input.config.test.timeoutSec ? input.config.test.timeoutSec * 1000 : undefined });
  }
  const task = value as Record<string, unknown>;
  const taskId = stringAt(task, ['taskId', 'id']);
  const title = stringAt(task, ['title']);
  const size = task.size;
  const prefix = `/tasks/${taskId ?? index}`;
  if (taskId === undefined) problems.push(`${prefix}.taskId is required`);
  if (title === undefined) problems.push(`${prefix}.title is required`);
  if (typeof size !== 'string' || !SIZES.has(size as TaskSize)) {
    problems.push(`${prefix}.size must be small, medium or large`);
  }
  if (taskId === undefined || title === undefined || typeof size !== 'string' || !SIZES.has(size as TaskSize)) return null;
  const outcomes = parseOutcomes(task.outcomes, problems, prefix);
  return {
    taskId,
    title,
    body: stringAt(task, ['body', 'description']) ?? '',
    issueNumber: numberAt(task, ['issueNumber', 'number']),
    issueUrl: stringAt(task, ['issueUrl', 'url']) ?? null,
    size: size as TaskSize,
    outcomes,
    scriptedAttempts: parseScriptedAttempts(task, outcomes, problems, prefix),
  };
}

